import { calculateOfficeRevenue } from "../../../shared/bookingFinancials";
import { ArrowRight, BusFront, CalendarDays, CheckCircle2, Clock3, MessageCircle, PackagePlus, Pencil, Printer, Save, TicketCheck, Trash2, UserRound, WalletCards, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { type ReservationItem, type TripItem, useBookingStore } from "../stores/bookingStore";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import { startLogin } from "@/const";
import * as XLSX from "xlsx";

type TripDetailProps = { tripCode: string };

const statusLabel: Record<TripItem["status"], string> = { open: "متاحة للحجز", boarding: "مرحلة التجهيز", departed: "انطلقت", closed: "مغلقة" };
const statusTone: Record<TripItem["status"], string> = { open: "tag-green", boarding: "tag-amber", departed: "tag-blue", closed: "tag-red" };

function currency(value: number) { return new Intl.NumberFormat("ar-SA", { maximumFractionDigits: 2 }).format(value); }
function escapePrintHtml(value: unknown) { return String(value ?? "").replace(/[&<>'"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" }[char] ?? char)); }

function printDriverManifest(data: any) {
  const printable = window.open("", "_blank", "width=1040,height=760");
  if (!printable) { toast.error("تعذر فتح كشف السائق. اسمح بالنوافذ المنبثقة ثم أعد المحاولة."); return; }
  const trip = data.trip ?? {}; const branch = data.branch ?? {}; const reservations = data.reservations ?? []; const trusts = data.trusts ?? [];
  const passengerRows = reservations.map((item: any, index: number) => `<tr><td class="index">${index + 1}</td><td><b class="seat">${escapePrintHtml(item.seatNumber)}</b></td><td><strong>${escapePrintHtml(item.passengerName)}</strong><small>${escapePrintHtml(item.passengerType ?? "—")} · ${escapePrintHtml(item.nationality ?? "—")}</small></td><td dir="ltr" class="phone">${escapePrintHtml(item.phone)}</td><td>${escapePrintHtml(item.luggageCount ?? 0)}</td><td class="mono">${escapePrintHtml(item.reservationCode)}</td></tr>`).join("");
  const trustRows = trusts.map((item: any, index: number) => `<tr><td class="index">${index + 1}</td><td class="mono">${escapePrintHtml(item.trustCode)}</td><td><strong>${escapePrintHtml(item.senderName)}</strong><small dir="ltr">${escapePrintHtml(item.senderPhone)}</small></td><td><strong>${escapePrintHtml(item.recipientName)}</strong><small dir="ltr">${escapePrintHtml(item.recipientPhone)}</small></td><td>${escapePrintHtml(item.itemDescription)}<small>العدد: ${escapePrintHtml(item.itemCount ?? 1)}</small></td><td><span class="status">${escapePrintHtml(item.status === "delivered" ? "تم التسليم" : "بانتظار التسليم")}</span></td></tr>`).join("");
  const tripTime = trip.departureAt ? new Date(trip.departureAt).toLocaleString("ar-SA") : "—";
  printable.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>كشف تشغيل السائق ${escapePrintHtml(trip.code)}</title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{margin:0;color:#173f38;font-family:Tahoma,Arial,sans-serif;font-size:11px;line-height:1.45}.sheet{max-width:1120px;margin:0 auto}.brand-line{height:8px;background:linear-gradient(90deg,#e7ae59 0 18%,#1d6a58 18% 100%)}.branch-head{padding:13px 18px 11px;text-align:center;border:1px solid #d9e8df;border-top:0;background:linear-gradient(135deg,#fbfdfb,#eff8f2)}.branch-head .kicker{margin:0;color:#6e8a80;font-size:9px;font-weight:700;letter-spacing:.08em}.branch-head h1{margin:3px 0 0;color:#173f38;font-size:23px}.branch-head p{margin:3px 0 0;color:#668178;font-size:10px}.trip-code{position:absolute;top:19px;left:18px;border-radius:9px;background:#173f38;color:#fff;padding:7px 10px;font-family:Arial,sans-serif;font-size:11px;font-weight:bold}.meta{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:12px 0}.meta div{min-height:52px;border:1px solid #dfece5;border-radius:8px;padding:8px 10px;background:#fff}.label{display:block;color:#738f85;font-size:8px;font-weight:700}.value{display:block;margin-top:3px;color:#244d42;font-size:11px;font-weight:700}.section{margin-top:11px;overflow:hidden;border:1px solid #dce9e2;border-radius:9px}.section-head{display:flex;align-items:center;justify-content:space-between;padding:8px 11px;background:#f2f8f4;border-bottom:1px solid #dce9e2}.section-head h2{margin:0;color:#1c5b4c;font-size:13px}.count{border-radius:999px;background:#dcefe5;color:#286d59;padding:3px 8px;font-size:8px;font-weight:700}table{width:100%;border-collapse:collapse;font-size:9px}th{background:#173f38;color:#fff;padding:8px 7px;text-align:right;font-size:8px;white-space:nowrap}td{padding:7px;border-bottom:1px solid #e7efea;vertical-align:middle}tbody tr:nth-child(even){background:#fbfdfc}tbody tr:last-child td{border-bottom:0}.index{width:24px;text-align:center;color:#799188}.seat{display:inline-grid;min-width:22px;place-items:center;border-radius:5px;background:#e3f2eb;color:#1e7459;padding:2px 5px}.mono{direction:ltr;text-align:right;color:#315f53;font-family:Arial,sans-serif;font-size:8px;font-weight:700}.phone{font-family:Arial,sans-serif;color:#365e53}small{display:block;margin-top:2px;color:#849990;font-size:8px}.status{border-radius:999px;background:#fff2d6;color:#9a6b1c;padding:3px 6px;font-size:8px;font-weight:700}.empty{padding:22px;text-align:center;color:#789088}.footer{display:flex;justify-content:space-between;gap:12px;margin-top:12px;border-top:1px solid #dce9e2;padding-top:8px;color:#789088;font-size:8px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.section{break-inside:avoid}}</style></head><body><main class="sheet"><div class="brand-line"></div><header class="branch-head"><span class="trip-code">${escapePrintHtml(trip.code)}</span><p class="kicker">SUHOUD BUS · كشف تشغيل السائق</p><h1>${escapePrintHtml(branch.name ?? "حافلة سهود")}</h1><p>كشف ركاب وأمانات الرحلة · وثيقة تشغيلية قابلة للحفظ بصيغة PDF</p></header><section class="meta"><div><span class="label">المسار</span><span class="value">${escapePrintHtml(trip.routeName)}</span></div><div><span class="label">موعد الرحلة</span><span class="value">${escapePrintHtml(tripTime)}</span></div><div><span class="label">رقم الحافلة</span><span class="value">${escapePrintHtml(trip.busNumber)}</span></div><div><span class="label">السائق الأول</span><span class="value">${escapePrintHtml(trip.primaryDriverName)}</span></div><div><span class="label">السائق الثاني</span><span class="value">${escapePrintHtml(trip.secondDriverName ?? "غير محدد")}</span></div></section><section class="section"><div class="section-head"><h2>قائمة الركاب</h2><span class="count">${reservations.length} راكب</span></div>${reservations.length ? `<table><thead><tr><th>#</th><th>المقعد</th><th>اسم الراكب</th><th>الجوال</th><th>الشنط</th><th>رقم التذكرة</th></tr></thead><tbody>${passengerRows}</tbody></table>` : '<div class="empty">لا توجد حجوزات ركاب مسجلة لهذه الرحلة.</div>'}</section><section class="section"><div class="section-head"><h2>قائمة الأمانات</h2><span class="count">${trusts.length} أمانات</span></div>${trusts.length ? `<table><thead><tr><th>#</th><th>رقم الأمانة</th><th>المرسل</th><th>المستلم</th><th>وصف الأمانة</th><th>الحالة</th></tr></thead><tbody>${trustRows}</tbody></table>` : '<div class="empty">لا توجد أمانات مسجلة لهذه الرحلة.</div>'}</section><footer class="footer"><span>الفرع: ${escapePrintHtml(branch.name ?? "—")}</span><span>إجمالي الركاب: ${reservations.length} · إجمالي الأمانات: ${trusts.length}</span><span>تاريخ الاستخراج: ${escapePrintHtml(new Date().toLocaleString("ar-SA"))}</span></footer></main><script>window.print()</script></body></html>`);
  printable.document.close();
}

export default function TripDetail({ tripCode }: TripDetailProps) {
  const navigate = useNavigate();
  const location = useLocation();
  const trips = useBookingStore(state => state.trips);
  const setReservations = useBookingStore(state => state.setReservations);
  const { isAuthenticated } = useAuth();
  const trip = trips.find(item => item.code === tripCode);
  const remoteReservations = trpc.mongoBooking.reservations.listByTrip.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false, refetchOnWindowFocus: true, refetchInterval: 4_000, refetchIntervalInBackground: false });
  const driverManifest = trpc.mongoBooking.trips.driverManifest.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false, refetchOnWindowFocus: true, refetchInterval: 8_000, refetchIntervalInBackground: false });
  const startTrip = trpc.mongoBooking.trips.start.useMutation({ onSuccess: () => { toast.success("تم تسجيل انطلاق الرحلة."); void driverManifest.refetch(); }, onError: error => toast.error(error.message) });
  useEffect(() => {
    if (!remoteReservations.data) return;
    setReservations(remoteReservations.data.map(item => ({
      id: String(item.reservationCode),
      tripCode: String(item.tripCode),
      passengerName: String(item.passengerName),
      phone: String(item.phone),
      nationality: String(item.nationality),
      passportNumber: String(item.passportNumber),
      birthDate: item.birthDate ? String(item.birthDate) : "",
      luggageCount: Number(item.luggageCount ?? 0),
      passengerType: item.passengerType as ReservationItem["passengerType"],
      paymentMethod: item.paymentMethod as ReservationItem["paymentMethod"],
      seatNumber: Number(item.seatNumber),
      ticketPrice: Number(item.ticketPrice),
      driverCommission: Number(item.driverCommission),
      officeRevenue: Number(item.officeRevenue),
      branchContactPhone: item.branchContactPhone ? String(item.branchContactPhone) : "",
      createdAt: item.createdAt instanceof Date ? item.createdAt.toISOString() : String(item.createdAt),
    })));
  }, [remoteReservations.data, setReservations]);
  const requestedSeat = Number(new URLSearchParams(location.search).get("seat"));
  const canOpenRequestedSeat = Boolean(trip && Number.isInteger(requestedSeat) && requestedSeat >= 1 && requestedSeat <= trip.capacity && !trip.bookedSeats.includes(requestedSeat));
  const [selectedSeat, setSelectedSeat] = useState<number | null>(() => canOpenRequestedSeat ? requestedSeat : null);
  const [bookingOpen, setBookingOpen] = useState(() => canOpenRequestedSeat);
  const [editingOpen, setEditingOpen] = useState(false);
  const [editingReservation, setEditingReservation] = useState<ReservationItem | null>(null);
  const [trustOpen, setTrustOpen] = useState(false);

  useEffect(() => {
    if (selectedSeat && trip?.bookedSeats.includes(selectedSeat)) {
      setSelectedSeat(null);
      setBookingOpen(false);
      toast.info("تم حجز هذا المقعد من مستخدم آخر؛ تم تحديث خريطة المقاعد.");
    }
  }, [selectedSeat, trip?.bookedSeats]);

  if (!trip) return <section className="soft-card p-8 text-center"><BusFront className="mx-auto text-[#83928d]" size={34} /><h1 className="mt-4 text-lg font-extrabold text-[#173f38]">الرحلة غير موجودة</h1><button className="action-primary mt-5" onClick={() => navigate("/trips")}>العودة إلى الرحلات</button></section>;

  const availableSeats = trip.capacity - trip.bookedSeats.length;
  const seats = Array.from({ length: trip.capacity }, (_, index) => index + 1);
  const chooseSeat = (seat: number) => {
    if (trip.bookedSeats.includes(seat)) return;
    setSelectedSeat(seat);
    setBookingOpen(true);
  };
  const exportDriverManifest = async (start = false) => {
    if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لاستخراج كشف السائق."); startLogin(); return; }
    if (start && !window.confirm("هل تريد تسجيل انطلاق الرحلة وإصدار كشف الركاب للسائق الآن؟")) return;
    if (start) await startTrip.mutateAsync({ tripCode });
    const result = await driverManifest.refetch();
    if (!result.data) { toast.error("تعذر تجهيز كشف السائق."); return; }
    printDriverManifest(result.data);
  };

  return <>
    <div className="mb-7 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
      <div>
        <button className="mb-4 inline-flex items-center gap-2 text-[11px] font-bold text-[#5e7b72] transition hover:text-[#173f38]" onClick={() => navigate("/trips")}><ArrowRight size={15} /> العودة إلى الرحلات</button>
        <p className="page-kicker">تفاصيل التشغيل · {trip.code}</p>
        <h1 className="page-title">{trip.route}</h1>
        <p className="page-subtitle">إدارة بيانات الرحلة والمقاعد والحجوزات والتحصيل المالي من شاشة واحدة.</p>
      </div>
      <div className="flex flex-wrap gap-2"><button className="action-primary" onClick={() => void exportDriverManifest(true)} disabled={startTrip.isPending}><BusFront size={15} /> {startTrip.isPending ? "جارٍ بدء الرحلة..." : "بدء الرحلة وكشف PDF"}</button><button className="action-secondary" onClick={() => void exportDriverManifest()}><Printer size={15} /> كشف السائق PDF</button><button className="action-secondary" onClick={() => setTrustOpen(true)}><PackagePlus size={15} /> إضافة أمانة</button><button className="action-secondary" onClick={() => setEditingOpen(true)}><Pencil size={15} /> تعديل الرحلة</button><span className={`tag self-center ${statusTone[trip.status]}`}>{statusLabel[trip.status]}</span></div>
    </div>

    <section className="trip-hero soft-card overflow-hidden">
      <div className="trip-hero-main"><div className="trip-vehicle"><BusFront size={27} /></div><div><p className="text-[10px] text-white/55">الحافلة</p><p className="mt-1 text-base font-extrabold text-white">{trip.bus}</p></div><div className="trip-route-line" /><div><p className="text-[10px] text-white/55">المغادرة</p><p className="mt-1 flex items-center gap-1.5 text-sm font-bold text-white"><CalendarDays size={14} /> {trip.date}</p></div><div><p className="text-[10px] text-white/55">الوقت</p><p className="mt-1 flex items-center gap-1.5 text-sm font-bold text-white"><Clock3 size={14} /> {trip.time}</p></div></div>
      <div className="trip-hero-stats"><span><strong>{trip.capacity}</strong> مقعداً</span><span><strong>{trip.bookedSeats.length}</strong> محجوز</span><span><strong>{availableSeats}</strong> متاح</span></div>
    </section>

    <div className="mt-5 grid gap-5 xl:grid-cols-[.74fr_1.26fr]">
      <section className="soft-card p-5"><div className="flex items-center justify-between"><div><h2 className="section-title">بيانات الحافلة</h2><p className="mt-1 section-meta">طاقم التشغيل المعتمد للرحلة</p></div><BusFront size={19} className="text-[#4a8877]" /></div><div className="mt-5 space-y-4"><InfoRow label="رقم الحافلة" value={trip.bus} /><InfoRow label="السائق الأول" value={trip.driver} icon={<UserRound size={14} />} /><InfoRow label="السائق الثاني" value={trip.secondDriver} icon={<UserRound size={14} />} /><InfoRow label="المسار" value={trip.route} />{trip.sharedBranchName && <InfoRow label="إتاحة الحجز" value={`رحلة مشتركة مع ${trip.sharedBranchName}`} />}<InfoRow label="إجمالي المقاعد" value={`${trip.capacity} مقعد`} /></div><TripFinancialSummary tripCode={trip.code} /></section>
      <section className="soft-card p-5"><div className="flex flex-col gap-3 border-b border-[#edf0ed] pb-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="section-title">خريطة المقاعد</h2><p className="mt-1 section-meta">تتحدث تلقائياً كل بضع ثوانٍ؛ اختر أي مقعد متاح لفتح نموذج الحجز مباشرة.</p></div><div className="flex gap-3 text-[9px] text-[#78918a]"><span className="flex items-center gap-1"><i className="h-2.5 w-2.5 rounded bg-[#edf4ef] ring-1 ring-[#b8d8c6]" /> متاح</span><span className="flex items-center gap-1"><i className="h-2.5 w-2.5 rounded bg-[#fdeae5] ring-1 ring-[#f0b2a1]" /> محجوز</span><span className="flex items-center gap-1"><i className="h-2.5 w-2.5 rounded bg-[#d9efe4] ring-1 ring-[#5c9e82]" /> محدد</span></div></div><div className="bus-layout mt-6"><div className="bus-front"><BusFront size={16} /> مقدمة الحافلة</div><div className="seat-map">{seats.map(seat => { const booked = trip.bookedSeats.includes(seat); return <button key={seat} onClick={() => chooseSeat(seat)} disabled={booked} className={`trip-seat ${booked ? "trip-seat-booked" : ""} ${selectedSeat === seat ? "trip-seat-selected" : ""}`}><span>{seat}</span><small>{booked ? "محجوز" : "متاح"}</small></button>; })}</div></div><p className="mt-5 text-center text-[10px] text-[#7c928a]">المقاعد مرتبة رقمياً من 1 إلى {trip.capacity}. يمنع الخادم حجز المقعد نفسه حتى عند محاولة الحجز في اللحظة نفسها.</p></section>
    </div>
    <TripReservations tripCode={trip.code} onEdit={setEditingReservation} />
    <ReservationEditPicker tripCode={trip.code} onEdit={setEditingReservation} />
    <TrustList tripCode={trip.code} />
    {bookingOpen && selectedSeat !== null && <TicketModal trip={trip} seatNumber={selectedSeat} onClose={() => { setBookingOpen(false); setSelectedSeat(null); }} />}
    {editingReservation && <ReservationEditModal reservation={editingReservation} onClose={() => setEditingReservation(null)} />}
    {editingOpen && <TripEditModal trip={trip} onClose={() => setEditingOpen(false)} />}
    {trustOpen && <TrustModal tripCode={trip.code} onClose={() => setTrustOpen(false)} />}
  </>;
}

function InfoRow({ label, value, icon }: { label: string; value: string; icon?: React.ReactNode }) { return <div className="flex items-center justify-between gap-4 border-b border-[#eff2ef] pb-3 last:border-0 last:pb-0"><span className="text-[10px] text-[#80908c]">{label}</span><span className="flex items-center gap-1.5 text-[11px] font-bold text-[#334f47]">{icon}{value}</span></div>; }

function TripFinancialSummary({ tripCode }: { tripCode: string }) {
  const { isAuthenticated } = useAuth();
  const reservations = useBookingStore(state => state.reservations);
  const remoteReport = trpc.mongoBooking.reports.tripRevenue.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false, refetchOnWindowFocus: false });
  const localRows = reservations.filter(item => item.tripCode === tripCode);
  const totalTicketSales = Number(remoteReport.data?.totalTicketSales ?? localRows.reduce((sum, item) => sum + item.ticketPrice, 0));
  const totalDriverCommission = Number(remoteReport.data?.totalDriverCommission ?? localRows.reduce((sum, item) => sum + item.driverCommission, 0));
  const officeRevenue = Number(remoteReport.data?.officeRevenue ?? localRows.reduce((sum, item) => sum + item.officeRevenue, 0));
  const trustRevenue = Number(remoteReport.data?.totalTrustRevenue ?? 0);
  const trustDriverCommission = Number(remoteReport.data?.totalTrustDriverCommission ?? 0);
  return <div className="mt-6 rounded-xl border border-[#e4eee7] bg-[#f6faf6] p-4"><p className="text-[10px] font-bold text-[#46665d]">ملخص إيرادات الرحلة</p><div className="mt-4 grid grid-cols-2 gap-3 text-[10px]"><FinanceStat label="إجمالي قيمة التذاكر" value={totalTicketSales} tone="blue" /><FinanceStat label="عمولات السائق للتذاكر" value={totalDriverCommission} tone="amber" /><FinanceStat label="صافي الأمانات للمكتب" value={trustRevenue} tone="purple" /><FinanceStat label="عمولات سائق الأمانات" value={trustDriverCommission} tone="amber" /><FinanceStat label="إجمالي صافي إيراد المكتب" value={officeRevenue} tone="green" /></div><TripReportActions tripCode={tripCode} /></div>;
}

function FinanceStat({ label, value, tone }: { label: string; value: number; tone: string }) { return <div className={`finance-stat finance-${tone}`}><span>{label}</span><strong>{currency(value)} ر.س</strong></div>; }
function StatusBadge({ label, tone }: { label: string; tone: "green" | "amber" }) { return <span className={`tag tag-${tone}`}>{label}</span>; }

function TripReportActions({ tripCode }: { tripCode: string }) {
  const { isAuthenticated } = useAuth();
  const report = trpc.mongoBooking.reports.tripRevenue.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false });
  const trusts = trpc.mongoBooking.trusts.listByTrip.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false });
  const allReservations = useBookingStore(state => state.reservations);
  const trip = useBookingStore(state => state.trips.find(item => item.code === tripCode));
  const reservations = useMemo(() => allReservations.filter(item => item.tripCode === tripCode), [allReservations, tripCode]);
  const branchContactPhone = reservations.find(item => item.branchContactPhone)?.branchContactPhone ?? "";
  const requireLogin = () => { if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لتصدير بيانات الرحلة الفعلية."); startLogin(); return false; } return true; };
  const exportExcel = () => { if (!requireLogin()) return; const info = report.data; const rows: (string | number)[][] = [["تقرير رحلة حافلة سهود", tripCode], ["إجمالي قيمة التذاكر", Number(info?.totalTicketSales ?? 0)], ["عمولات سائق التذاكر", Number(info?.totalDriverCommission ?? 0)], ["رسوم الأمانات", Number(info?.totalTrustFees ?? 0)], ["عمولات سائق الأمانات", Number(info?.totalTrustDriverCommission ?? 0)], ["صافي الأمانات للمكتب", Number(info?.totalTrustRevenue ?? 0)], ["إجمالي صافي إيراد المكتب", Number(info?.officeRevenue ?? 0)], [], ["رقم التذكرة", "الراكب", "المقعد", "السعر", "عمولة السائق", "إيراد المكتب", "تواصل الفرع"]]; reservations.forEach(item => rows.push([item.id, item.passengerName, item.seatNumber, item.ticketPrice, item.driverCommission, item.officeRevenue, item.branchContactPhone || "—"])); rows.push([], ["رقم الأمانة", "المرسل", "المستلم", "الوصف", "الرسوم", "عمولة السائق", "صافي المكتب", "الحالة"]); (trusts.data ?? []).forEach(item => rows.push([String(item.trustCode), String(item.senderName), String(item.recipientName), String(item.itemDescription), Number(item.fee ?? item.price ?? 0), Number(item.driverCommission ?? 0), Number(item.officeRevenue ?? (Number(item.fee ?? item.price ?? 0) - Number(item.driverCommission ?? 0))), item.status === "delivered" ? "تم التسليم" : "بانتظار التسليم"])); const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet(rows), "تقرير الرحلة"); XLSX.writeFile(book, `تقرير-${tripCode}.xlsx`); };
  const printReport = () => {
    if (!requireLogin()) return;
    const info = report.data;
    const printable = window.open("", "_blank", "width=1100,height=820");
    if (!printable) { toast.error("تعذر فتح نافذة التقرير. اسمح بالنوافذ المنبثقة ثم أعد المحاولة."); return; }
    const amount = (value: unknown) => `${currency(Number(value ?? 0))} ر.س`;
    const tripDate = trip?.date ? `${trip.date}${trip.time ? ` · ${trip.time}` : ""}` : "موعد الرحلة غير مسجل";
    const financialCards = [
      { label: "إجمالي مبيعات التذاكر", value: amount(info?.totalTicketSales), tone: "blue" },
      { label: "عمولات سائق التذاكر", value: amount(info?.totalDriverCommission), tone: "gold" },
      { label: "رسوم الأمانات", value: amount(info?.totalTrustFees), tone: "purple" },
      { label: "صافي الأمانات للمكتب", value: amount(info?.totalTrustRevenue), tone: "teal" },
      { label: "إجمالي صافي إيراد المكتب", value: amount(info?.officeRevenue), tone: "green" },
      { label: "الحجوزات المسجلة", value: `${reservations.length} تذكرة`, tone: "slate" },
    ].map(card => `<article class="metric ${card.tone}"><span>${escapePrintHtml(card.label)}</span><strong>${escapePrintHtml(card.value)}</strong></article>`).join("");
    const reservationRows = reservations.map((item, index) => `<tr><td class="index">${index + 1}</td><td class="mono">${escapePrintHtml(item.id)}</td><td><strong>${escapePrintHtml(item.passengerName)}</strong><small dir="ltr">${escapePrintHtml(item.phone)}</small></td><td><b class="seat">${escapePrintHtml(item.seatNumber)}</b></td><td>${escapePrintHtml(item.paymentMethod)}</td><td>${escapePrintHtml(amount(item.ticketPrice))}</td><td class="positive">${escapePrintHtml(amount(item.officeRevenue))}</td></tr>`).join("");
    const trustRows = (trusts.data ?? []).map((item, index) => `<tr><td class="index">${index + 1}</td><td class="mono">${escapePrintHtml(item.trustCode)}</td><td>${escapePrintHtml(item.senderName)}<small dir="ltr">${escapePrintHtml(item.senderPhone)}</small></td><td>${escapePrintHtml(item.recipientName)}<small dir="ltr">${escapePrintHtml(item.recipientPhone)}</small></td><td>${escapePrintHtml(item.itemDescription)} × ${escapePrintHtml(item.itemCount)}</td><td>${escapePrintHtml(amount(item.fee ?? item.price))}</td><td class="positive">${escapePrintHtml(amount(item.officeRevenue ?? (Number(item.fee ?? item.price ?? 0) - Number(item.driverCommission ?? 0))))}</td></tr>`).join("");
    printable.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تقرير رحلة ${escapePrintHtml(tripCode)} | حافلة سهود</title><style>@page{size:A4;size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{margin:0;background:#fff;color:#173f38;font-family:Tahoma,Arial,sans-serif;font-size:11px;line-height:1.55}.report{max-width:1120px;margin:0 auto}.brandbar{height:8px;background:linear-gradient(90deg,#e9b15f 0 18%,#1f6b5a 18% 100%)}.header{display:flex;justify-content:space-between;align-items:flex-start;padding:18px 20px 14px;border:1px solid #d9e8df;border-top:0;background:linear-gradient(135deg,#fbfdfb 0%,#eff7f2 100%)}.eyebrow{margin:0 0 5px;color:#69867d;font-size:9px;font-weight:700;letter-spacing:.08em}.header h1{margin:0;color:#173f38;font-size:24px;letter-spacing:-.02em}.header p{margin:5px 0 0;color:#648077;font-size:10px}.trip-code{min-width:118px;border-radius:11px;background:#173f38;color:#fff;padding:10px 13px;text-align:center;box-shadow:0 5px 14px rgba(23,63,56,.12)}.trip-code span{display:block;font-size:8px;opacity:.72}.trip-code strong{display:block;margin-top:2px;font-family:Arial,sans-serif;font-size:14px;letter-spacing:.03em}.metadata{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:12px 0}.metadata div{min-height:50px;border:1px solid #e0ebe5;border-radius:8px;background:#fff;padding:8px 10px}.label{display:block;color:#759087;font-size:8px;font-weight:700}.value{display:block;margin-top:3px;color:#244b41;font-size:11px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:4px 0 15px}.metric{border:1px solid #e0ebe5;border-radius:9px;padding:9px 10px;background:#fff;min-height:59px;border-top-width:3px}.metric span{display:block;color:#6e877e;font-size:8px;font-weight:700}.metric strong{display:block;margin-top:5px;color:#193f36;font-size:13px}.metric.blue{border-top-color:#4482a7}.metric.gold{border-top-color:#cf932d}.metric.purple{border-top-color:#8464a3}.metric.teal{border-top-color:#3f8b76}.metric.green{border-top-color:#237459;background:#f4faf6}.metric.slate{border-top-color:#718a84}.section{margin-top:13px;border:1px solid #dce9e2;border-radius:9px;overflow:hidden}.section-head{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;background:#f3f8f5;border-bottom:1px solid #dce9e2}.section-head h2{margin:0;color:#1b584a;font-size:13px}.section-head span{border-radius:999px;background:#dcefe5;color:#286d59;padding:3px 8px;font-size:8px;font-weight:700}table{width:100%;border-collapse:collapse;font-size:9px}th{background:#173f38;color:#fff;padding:8px 7px;text-align:right;font-size:8px;font-weight:700;white-space:nowrap}td{border-bottom:1px solid #e7efea;padding:7px;vertical-align:middle}tbody tr:nth-child(even){background:#fbfdfc}tbody tr:last-child td{border-bottom:0}.index{width:25px;color:#759087;text-align:center}.mono{direction:ltr;text-align:right;color:#315f53;font-family:Arial,sans-serif;font-size:8px;font-weight:700}.seat{display:inline-grid;min-width:21px;place-items:center;border-radius:5px;background:#e4f2eb;color:#227258;padding:2px 5px}.positive{color:#167056;font-weight:700}small{display:block;margin-top:1px;color:#849891;font-size:8px}.empty{padding:24px;text-align:center;color:#789088}.footer{display:flex;justify-content:space-between;gap:15px;margin-top:13px;border-top:1px solid #dce9e2;padding-top:8px;color:#789088;font-size:8px}.footer strong{color:#486a60}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}.report{max-width:none}.section{break-inside:avoid}table{break-inside:auto}tr{break-inside:avoid;break-after:auto}}</style></head><body><main class="report"><div class="brandbar"></div><header class="header"><div><p class="eyebrow">SUHOUD BUS · إدارة التشغيل والحجوزات</p><h1>تقرير تشغيلي للرحلة</h1><p>ملخص الحجوزات والأمانات والإيرادات — وثيقة داخلية قابلة للحفظ بصيغة PDF</p></div><div class="trip-code"><span>رقم الرحلة</span><strong>${escapePrintHtml(tripCode)}</strong></div></header><section class="metadata"><div><span class="label">المسار</span><span class="value">${escapePrintHtml(trip?.route ?? "—")}</span></div><div><span class="label">موعد المغادرة</span><span class="value">${escapePrintHtml(tripDate)}</span></div><div><span class="label">الحافلة والسائق</span><span class="value">${escapePrintHtml(trip?.bus ?? "—")} · ${escapePrintHtml(trip?.driver ?? "—")}</span></div><div><span class="label">تواصل الفرع</span><span class="value" dir="ltr">${escapePrintHtml(branchContactPhone || "—")}</span></div></section><section class="metrics">${financialCards}</section><section class="section"><div class="section-head"><h2>سجل الحجوزات</h2><span>${reservations.length} تذكرة</span></div>${reservations.length ? `<table><thead><tr><th>#</th><th>رقم التذكرة</th><th>الراكب</th><th>المقعد</th><th>الدفع</th><th>قيمة التذكرة</th><th>إيراد المكتب</th></tr></thead><tbody>${reservationRows}</tbody></table>` : '<div class="empty">لا توجد حجوزات مسجلة لهذه الرحلة.</div>'}</section>${(trusts.data ?? []).length ? `<section class="section"><div class="section-head"><h2>سجل الأمانات</h2><span>${(trusts.data ?? []).length} أمانات</span></div><table><thead><tr><th>#</th><th>رقم الأمانة</th><th>المرسل</th><th>المستلم</th><th>الوصف</th><th>الرسوم</th><th>صافي المكتب</th></tr></thead><tbody>${trustRows}</tbody></table></section>` : ""}<footer class="footer"><span><strong>حافلة سهود</strong> · تقرير داخلي للاستخدام التشغيلي</span><span>أُنشئ في ${escapePrintHtml(new Date().toLocaleString("ar-SA"))}</span><span>صفحة <span class="page-number"></span></span></footer></main><script>window.print()</script></body></html>`);
    printable.document.close();
  };
  return <div className="mt-4 flex gap-2"><button className="report-action" onClick={exportExcel}>تصدير Excel</button><button className="report-action" onClick={printReport}>طباعة / PDF</button></div>;
}

function printTicket(item: ReservationItem) {
  const ticketWindow = window.open("", "_blank", "width=760,height=700");
  if (!ticketWindow) { toast.error("تعذر فتح نافذة الطباعة. اسمح بالنوافذ المنبثقة ثم أعد المحاولة."); return; }
  ticketWindow.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><title>تذكرة ${item.id}</title><style>body{font-family:Arial,sans-serif;margin:36px;color:#173f38}.ticket{border:2px solid #173f38;border-radius:16px;overflow:hidden}.head{background:#173f38;color:#fff;padding:24px}.head h1{margin:0;font-size:26px}.head p{margin:8px 0 0;color:#d4e8dc}.body{padding:24px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.item{border-bottom:1px solid #e5ece7;padding-bottom:10px}.label{font-size:12px;color:#71837d}.value{font-weight:700;margin-top:5px}.financial{margin-top:22px;background:#f2faf4;padding:16px;border-radius:10px}@media print{body{margin:0}}</style></head><body><section class="ticket"><header class="head"><h1>حافلة سهود</h1><p>تذكرة حجز · ${item.id}</p></header><main class="body"><div class="grid"><div class="item"><div class="label">اسم المسافر</div><div class="value">${item.passengerName}</div></div><div class="item"><div class="label">رقم الهاتف</div><div class="value">${item.phone}</div></div><div class="item"><div class="label">رقم المقعد</div><div class="value">${item.seatNumber}</div></div><div class="item"><div class="label">طريقة الدفع</div><div class="value">${item.paymentMethod}</div></div><div class="item"><div class="label">الجنسية</div><div class="value">${item.nationality}</div></div><div class="item"><div class="label">رقم الجواز</div><div class="value">${item.passportNumber}</div></div>${item.branchContactPhone ? `<div class="item"><div class="label">تواصل الفرع</div><div class="value" dir="ltr">${item.branchContactPhone}</div></div>` : ""}</div><div class="financial"><div class="label">إجمالي قيمة التذكرة</div><div class="value">${currency(item.ticketPrice)} ر.س</div></div></main></section><script>window.print()</script></body></html>`);
  ticketWindow.document.close();
}

function TrustModal({ tripCode, onClose }: { tripCode: string; onClose: () => void }) {
  const { isAuthenticated } = useAuth();
  const utils = trpc.useUtils();
  const createTrust = trpc.mongoBooking.trusts.create.useMutation({ onSuccess: () => { utils.mongoBooking.trusts.listByTrip.invalidate({ tripCode }); utils.mongoBooking.reports.tripRevenue.invalidate({ tripCode }); utils.mongoBooking.cashbox.overview.invalidate(); utils.mongoBooking.reports.overview.invalidate(); toast.success("تم حفظ الأمانة واحتساب صافي المكتب."); onClose(); }, onError: () => toast.error("تعذر حفظ الأمانة في MongoDB.") });
  const [form, setForm] = useState({ senderName: "", senderPhone: "", recipientName: "", recipientPhone: "", itemDescription: "", itemCount: "1", fee: "0", driverCommission: "0", paymentMethod: "نقدي" as "نقدي" | "شبكة" });
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const financials = calculateOfficeRevenue(Number(form.fee), Number(form.driverCommission));
  const save = () => { if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لحفظ الأمانة بشكل دائم."); startLogin(); return; } if (!form.senderName.trim() || !form.senderPhone.trim() || !form.recipientName.trim() || !form.recipientPhone.trim() || !form.itemDescription.trim()) { toast.error("أكمل بيانات المرسل والمستلم ووصف الأمانة."); return; } createTrust.mutate({ tripCode, senderName: form.senderName, senderPhone: form.senderPhone, recipientName: form.recipientName, recipientPhone: form.recipientPhone, itemDescription: form.itemDescription, itemCount: Number(form.itemCount), fee: Number(form.fee), driverCommission: Number(form.driverCommission), paymentMethod: form.paymentMethod }); };
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="trust-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">الرحلة · {tripCode}</p><h2 id="trust-title" className="mt-1 text-lg font-extrabold text-[#173f38]">إضافة أمانة</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose} aria-label="إغلاق"><X size={19} /></button></div><div className="grid gap-4 p-6 sm:grid-cols-2"><FormInput label="اسم المرسل" value={form.senderName} onChange={value => update("senderName", value)} placeholder="اسم المرسل" /><FormInput label="رقم المرسل" value={form.senderPhone} onChange={value => update("senderPhone", value)} placeholder="05XXXXXXXX" direction="ltr" /><FormInput label="اسم المستلم" value={form.recipientName} onChange={value => update("recipientName", value)} placeholder="اسم المستلم" /><FormInput label="رقم المستلم" value={form.recipientPhone} onChange={value => update("recipientPhone", value)} placeholder="05XXXXXXXX" direction="ltr" /><FormInput label="وصف الأمانة" value={form.itemDescription} onChange={value => update("itemDescription", value)} placeholder="مثال: حقيبة ملابس" /><FormInput label="عدد الأغراض" value={form.itemCount} onChange={value => update("itemCount", value)} type="number" /><FormInput label="رسوم الأمانة" value={form.fee} onChange={value => update("fee", value)} type="number" /><FormInput label="عمولة السائق" value={form.driverCommission} onChange={value => update("driverCommission", value)} type="number" /><FormSelect label="طريقة الدفع" value={form.paymentMethod} onChange={value => update("paymentMethod", value)} options={["نقدي", "شبكة"]} /><label className="block text-[10px] font-bold text-[#4e6860] sm:col-span-2">صافي إيراد المكتب<input className="input-control mt-2 border-[#9ac8b0] bg-[#f2faf4] font-extrabold text-[#287a5d]" value={`${financials.valid ? currency(financials.officeRevenue) : "0"} ر.س`} readOnly /></label><div className="sm:col-span-2 rounded-xl bg-[#f7faf7] px-4 py-3 text-[10px] text-[#637a72]">المعادلة: <strong className="text-[#245f4e]">رسوم الأمانة − عمولة السائق = إيراد المكتب</strong>.</div></div><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" onClick={save} disabled={!financials.valid || !form.senderName.trim() || !form.senderPhone.trim() || !form.recipientName.trim() || !form.recipientPhone.trim() || !form.itemDescription.trim()}><PackagePlus size={15} /> حفظ الأمانة</button></div></div></div>;
}

function ReservationEditPicker({ tripCode, onEdit }: { tripCode: string; onEdit: (reservation: ReservationItem) => void }) {
  const allReservations = useBookingStore(state => state.reservations);
  const reservations = allReservations.filter(item => item.tripCode === tripCode);
  const [reservationCode, setReservationCode] = useState("");
  useEffect(() => { if (!reservations.some(item => item.id === reservationCode)) setReservationCode(reservations[0]?.id ?? ""); }, [reservationCode, reservations]);
  if (!reservations.length) return null;
  const selected = reservations.find(item => item.id === reservationCode) ?? reservations[0];
  return <section className="soft-card mt-5 p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="section-title">تعديل تذكرة قائمة</h2><p className="mt-1 section-meta">اختر التذكرة لتعديل بيانات العميل أو المقعد أو السعر أو العمولة.</p></div><div className="flex flex-wrap items-end gap-2"><label className="block text-[10px] font-bold text-[#4e6860]">التذكرة<select className="filter-select mt-2 min-w-48" value={selected.id} onChange={event => setReservationCode(event.target.value)}>{reservations.map(item => <option key={item.id} value={item.id}>{item.id} — {item.passengerName}</option>)}</select></label><button className="action-secondary" onClick={() => onEdit(selected)}><Pencil size={15} /> تعديل البيانات</button></div></div></section>;
}

function TripReservations({ tripCode, onEdit }: { tripCode: string; onEdit: (reservation: ReservationItem) => void }) {
  const allReservations = useBookingStore(state => state.reservations);
  const reservations = allReservations.filter(item => item.tripCode === tripCode);
  const { isAuthenticated } = useAuth();
  const utils = trpc.useUtils();
  const whatsappMessages = trpc.mongoBooking.whatsapp.messages.useQuery(undefined, { enabled: isAuthenticated, refetchInterval: 10_000 });
  const sendWhatsapp = trpc.mongoBooking.whatsapp.manualLink.useMutation({ onSuccess: result => { window.open(result.url, "_blank", "noopener,noreferrer"); toast.success("فُتحت محادثة واتساب برسالة التذكرة الجاهزة. اضغط إرسال من واتساب لتأكيد الإرسال."); void whatsappMessages.refetch(); }, onError: error => toast.error(error.message) });
  const cancelReservation = trpc.mongoBooking.reservations.cancel.useMutation({ onSuccess: () => { utils.mongoBooking.reservations.listByTrip.invalidate({ tripCode }); utils.mongoBooking.reports.tripRevenue.invalidate({ tripCode }); utils.mongoBooking.trips.list.invalidate(); toast.success("تم إلغاء الحجز وتحرير المقعد."); } });
  const cancel = (reservationCode: string) => { if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لإلغاء حجز محفوظ."); startLogin(); return; } if (window.confirm("هل تريد إلغاء هذا الحجز وتحرير مقعده؟")) cancelReservation.mutate({ reservationCode }); };
  return <section className="soft-card mt-5 overflow-hidden"><div className="flex items-center justify-between border-b border-[#edf0ed] p-5"><div><h2 className="section-title">تذاكر الرحلة</h2><p className="mt-1 section-meta">{reservations.length} حجوزات مسجلة على هذه الرحلة</p></div><TicketCheck size={19} className="text-[#4b8c77]" /></div>{reservations.length === 0 ? <div className="p-9 text-center text-[11px] text-[#81938d]">لا توجد حجوزات مسجلة. اختر مقعداً متاحاً لإضافة أول تذكرة.</div> : <div className="table-wrap"><table className="data-table"><thead><tr><th>رقم التذكرة</th><th>الراكب</th><th>المقعد</th><th>السعر</th><th>عمولة السائق</th><th>إيراد المكتب</th><th>الدفع</th><th>واتساب</th><th>الإجراءات</th></tr></thead><tbody>{reservations.map(item => <tr key={item.id}><td className="font-bold text-[#1e5b4d]">{item.id}</td><td><p className="font-semibold">{item.passengerName}</p><p className="mt-1 text-[9px] text-[#92a09c]" dir="ltr">{item.phone}</p></td><td><span className="rounded-lg bg-[#e9f5ee] px-2 py-1 font-bold text-[#30755e]">{item.seatNumber}</span></td><td>{currency(item.ticketPrice)} ر.س</td><td>{currency(item.driverCommission)} ر.س</td><td className="font-extrabold text-[#287a5d]">{currency(item.officeRevenue)} ر.س</td><td>{item.paymentMethod}</td><td><button className="table-action" onClick={() => { if (window.confirm(`إرسال تفاصيل الحجز ${item.id} عبر واتساب الآن؟`)) sendWhatsapp.mutate({ bookingType: "reservation", bookingCode: item.id }); }} title="إرسال تفاصيل الحجز عبر واتساب"><MessageCircle size={15} /></button><span className="mr-1 text-[10px] text-[#71827e]">{(whatsappMessages.data ?? []).filter(message => message.bookingType === "reservation" && message.bookingCode === item.id).length}</span></td><td><div className="flex gap-2"><button className="table-action table-print" onClick={() => printTicket(item)} title="طباعة التذكرة"><Printer size={15} /></button><button className="table-action table-delete" onClick={() => cancel(item.id)} title="إلغاء الحجز"><Trash2 size={15} /></button></div></td></tr>)}</tbody></table></div>}</section>;
}

function TrustList({ tripCode }: { tripCode: string }) {
  const { isAuthenticated } = useAuth();
  const utils = trpc.useUtils();
  const trusts = trpc.mongoBooking.trusts.listByTrip.useQuery({ tripCode }, { enabled: isAuthenticated, retry: false, refetchOnWindowFocus: false });
  const markDelivered = trpc.mongoBooking.trusts.markDelivered.useMutation({ onSuccess: () => { utils.mongoBooking.trusts.listByTrip.invalidate({ tripCode }); toast.success("تم تأكيد تسليم الأمانة."); } });
  const deliver = (trustCode: string) => { if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لإدارة الأمانات."); startLogin(); return; } if (window.confirm("هل تم تسليم هذه الأمانة؟")) markDelivered.mutate({ trustCode }); };
  const items = trusts.data ?? [];
  return <section className="soft-card mt-5 overflow-hidden"><div className="flex items-center justify-between border-b border-[#edf0ed] p-5"><div><h2 className="section-title">أمانات الرحلة</h2><p className="mt-1 section-meta">{items.length} أمانات مرتبطة بهذه الرحلة</p></div><PackagePlus size={19} className="text-[#7b58a1]" /></div>{!isAuthenticated ? <div className="p-7 text-center text-[11px] text-[#81938d]">سجّل الدخول لعرض وإدارة الأمانات المحفوظة.</div> : items.length === 0 ? <div className="p-7 text-center text-[11px] text-[#81938d]">لا توجد أمانات مسجلة لهذه الرحلة.</div> : <div className="table-wrap"><table className="data-table"><thead><tr><th>رقم الأمانة</th><th>المرسل</th><th>المستلم</th><th>الوصف</th><th>الرسوم</th><th>عمولة السائق</th><th>صافي المكتب</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{items.map(item => { const fee = Number(item.fee ?? item.price ?? 0); const commission = Number(item.driverCommission ?? 0); const officeRevenue = Number(item.officeRevenue ?? fee - commission); return <tr key={String(item.trustCode)}><td className="font-bold text-[#6a4b91]">{String(item.trustCode)}</td><td><p>{String(item.senderName)}</p><p className="mt-1 text-[9px] text-[#92a09c]" dir="ltr">{String(item.senderPhone)}</p></td><td><p>{String(item.recipientName)}</p><p className="mt-1 text-[9px] text-[#92a09c]" dir="ltr">{String(item.recipientPhone)}</p></td><td>{String(item.itemDescription)} × {Number(item.itemCount)}</td><td className="font-bold">{currency(fee)} ر.س</td><td className="text-[#a36b22]">{currency(commission)} ر.س</td><td className="font-extrabold text-[#287a5d]">{currency(officeRevenue)} ر.س</td><td><StatusBadge tone={item.status === "delivered" ? "green" : "amber"} label={item.status === "delivered" ? "تم التسليم" : "بانتظار التسليم"} /></td><td>{item.status === "delivered" ? <CheckCircle2 size={17} className="text-[#3b9270]" /> : <button className="text-[10px] font-bold text-[#2d7a60]" onClick={() => deliver(String(item.trustCode))}>تأكيد التسليم</button>}</td></tr>; })}</tbody></table></div>}</section>;
}

function TicketModal({ trip, seatNumber, onClose }: { trip: TripItem; seatNumber: number; onClose: () => void }) {
  const { isAuthenticated } = useAuth();
  const utils = trpc.useUtils();
  const saveMongoReservation = trpc.mongoBooking.reservations.create.useMutation({
    onSuccess: result => {
      utils.mongoBooking.reservations.listByTrip.invalidate({ tripCode: trip.code });
      utils.mongoBooking.trips.list.invalidate();
      utils.mongoBooking.reports.tripRevenue.invalidate({ tripCode: trip.code });
      utils.mongoBooking.cashbox.overview.invalidate();
      utils.mongoBooking.reports.overview.invalidate();
      toast.success(`تم إنشاء الحجز بنجاح · رقم التذكرة ${result.reservationCode}`);
      onClose();
    },
    onError: error => {
      void utils.mongoBooking.trips.list.invalidate();
      void utils.mongoBooking.reservations.listByTrip.invalidate({ tripCode: trip.code });
      toast.error(error.message || "تعذر حفظ الحجز. تم تحديث حالة المقاعد.");
    },
  });
  const [form, setForm] = useState({ passengerName: "", phone: "", nationality: "", passportNumber: "", birthDate: "", luggageCount: "0", passengerType: "بالغ" as ReservationItem["passengerType"], paymentMethod: "نقدي" as ReservationItem["paymentMethod"], ticketPrice: "", driverCommission: "" });
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const customerSearchInput = useMemo(() => ({ search: form.phone.trim() || form.passengerName.trim() }), [form.phone, form.passengerName]);
  const frequentCustomers = trpc.mongoBooking.customers.frequent.useQuery(customerSearchInput, { enabled: isAuthenticated && customerSearchInput.search.length >= 2, retry: false, refetchOnWindowFocus: false });
  const applyCustomer = (index: string) => {
    const customer = (frequentCustomers.data ?? [])[Number(index)]; if (!customer) return;
    setForm(current => ({ ...current, passengerName: String(customer.passengerName ?? ""), phone: String(customer.phone ?? ""), nationality: String(customer.nationality ?? ""), passportNumber: String(customer.passportNumber ?? ""), birthDate: String(customer.birthDate ?? ""), luggageCount: String(customer.luggageCount ?? 0), passengerType: customer.passengerType === "طفل" ? "طفل" : "بالغ" }));
    toast.success(`تم تعبئة بيانات العميل المتكرر: ${customer.passengerName}`);
  };
  const hasFinancialInputs = form.ticketPrice.trim() !== "";
  const financials = calculateOfficeRevenue(Number(form.ticketPrice), Number(form.driverCommission || 0));
  const save = () => { if (!form.passengerName.trim() || !form.phone.trim() || !form.nationality.trim() || !form.passportNumber.trim()) return; if (!hasFinancialInputs) { toast.error("أدخل سعر التذكرة الفعلي أولاً."); return; } if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لحفظ الحجز بشكل دائم."); startLogin(); return; } const payload = { tripCode: trip.code, passengerName: form.passengerName, phone: form.phone, nationality: form.nationality, passportNumber: form.passportNumber, birthDate: form.birthDate, luggageCount: Number(form.luggageCount || 0), passengerType: form.passengerType, paymentMethod: form.paymentMethod, seatNumber, ticketPrice: Number(form.ticketPrice), driverCommission: Number(form.driverCommission || 0) }; saveMongoReservation.mutate(payload); };
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="ticket-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">حجز مقعد {seatNumber} · {trip.code}</p><h2 id="ticket-title" className="mt-1 text-lg font-extrabold text-[#173f38]">بيانات التذكرة</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose} aria-label="إغلاق"><X size={19} /></button></div><div className="grid gap-4 p-6 md:grid-cols-3">{frequentCustomers.data?.length ? <label className="block text-[10px] font-bold text-[#4e6860] md:col-span-3">عميل متكرر — اختر لتعبئة بياناته<select className="input-control mt-2" defaultValue="" onChange={event => applyCustomer(event.target.value)}><option value="">اختر العميل</option>{frequentCustomers.data.map((customer, index) => <option key={`${customer.phone}-${index}`} value={index}>{customer.passengerName} — {customer.phone} ({customer.bookingCount} حجوزات)</option>)}</select></label> : null}<FormInput label="اسم العميل" value={form.passengerName} onChange={value => update("passengerName", value)} placeholder="اسم المسافر" /><FormInput label="الجنسية" value={form.nationality} onChange={value => update("nationality", value)} placeholder="الجنسية" /><FormInput label="رقم الهاتف" value={form.phone} onChange={value => update("phone", value)} placeholder="9665XXXXXXXX" direction="ltr" /><FormInput label="رقم الجواز" value={form.passportNumber} onChange={value => update("passportNumber", value)} placeholder="رقم الجواز" /><FormInput label="عدد الشنط" value={form.luggageCount} onChange={value => update("luggageCount", value)} type="number" /><FormInput label="تاريخ الميلاد" value={form.birthDate} onChange={value => update("birthDate", value)} type="date" /><FormSelect label="النوع" value={form.passengerType} onChange={value => update("passengerType", value)} options={["بالغ", "طفل"]} /><FormSelect label="نوع الدفع" value={form.paymentMethod} onChange={value => update("paymentMethod", value)} options={["نقدي", "شبكة"]} /><FormInput label="رقم المقعد" value={String(seatNumber)} onChange={() => undefined} readOnly /><FormInput label="إجمالي سعر التذكرة" value={form.ticketPrice} onChange={value => update("ticketPrice", value)} type="number" placeholder="أدخل السعر الفعلي" /><FormInput label="عمولة السائق (اختيارية)" value={form.driverCommission} onChange={value => update("driverCommission", value)} type="number" placeholder="اتركها فارغة عند عدم وجود عمولة" /><label className="block text-[10px] font-bold text-[#4e6860]">صافي إيراد المكتب<input className="input-control mt-2 border-[#9ac8b0] bg-[#f2faf4] font-extrabold text-[#287a5d]" value={hasFinancialInputs && financials.valid ? `${currency(financials.officeRevenue)} ر.س` : ""} placeholder="يُحسب تلقائياً بعد إدخال السعر" readOnly /></label><div className="md:col-span-3 rounded-xl bg-[#f7faf7] px-4 py-3 text-[10px] text-[#637a72]">المعادلة: <strong className="text-[#245f4e]">إجمالي سعر التذكرة − عمولة السائق = إيراد المكتب</strong>. تُحتسب العمولة صفراً عند ترك الحقل فارغاً.</div></div><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" onClick={save} disabled={!hasFinancialInputs || !financials.valid || !form.passengerName.trim() || !form.phone.trim() || !form.nationality.trim() || !form.passportNumber.trim()}><TicketCheck size={15} /> حفظ بيانات التذكرة</button></div></div></div>;
}

function ReservationEditModal({ reservation, onClose }: { reservation: ReservationItem; onClose: () => void }) {
  const { isAuthenticated } = useAuth();
  const utils = trpc.useUtils();
  const [form, setForm] = useState({ passengerName: reservation.passengerName, phone: reservation.phone, nationality: reservation.nationality, passportNumber: reservation.passportNumber, birthDate: reservation.birthDate, luggageCount: String(reservation.luggageCount), passengerType: reservation.passengerType, paymentMethod: reservation.paymentMethod, seatNumber: String(reservation.seatNumber), ticketPrice: String(reservation.ticketPrice), driverCommission: reservation.driverCommission ? String(reservation.driverCommission) : "" });
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const hasTicketPrice = form.ticketPrice.trim() !== "";
  const financials = calculateOfficeRevenue(Number(form.ticketPrice), Number(form.driverCommission || 0));
  const saveReservation = trpc.mongoBooking.reservations.update.useMutation({
    onSuccess: () => {
      void utils.mongoBooking.reservations.listByTrip.invalidate({ tripCode: reservation.tripCode });
      void utils.mongoBooking.reservations.list.invalidate();
      void utils.mongoBooking.trips.list.invalidate();
      void utils.mongoBooking.reports.tripRevenue.invalidate({ tripCode: reservation.tripCode });
      void utils.mongoBooking.cashbox.overview.invalidate();
      void utils.mongoBooking.reports.overview.invalidate();
      toast.success(`تم تحديث التذكرة ${reservation.id} بنجاح.`);
      onClose();
    },
    onError: error => toast.error(error.message),
  });
  const save = () => {
    if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لتعديل التذكرة."); startLogin(); return; }
    if (!form.passengerName.trim() || !form.phone.trim() || !form.nationality.trim() || !form.passportNumber.trim() || !hasTicketPrice || !financials.valid) return;
    saveReservation.mutate({ reservationCode: reservation.id, passengerName: form.passengerName, phone: form.phone, nationality: form.nationality, passportNumber: form.passportNumber, birthDate: form.birthDate, luggageCount: Number(form.luggageCount || 0), passengerType: form.passengerType, paymentMethod: form.paymentMethod, seatNumber: Number(form.seatNumber), ticketPrice: Number(form.ticketPrice), driverCommission: Number(form.driverCommission || 0) });
  };
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="edit-ticket-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">تذكرة {reservation.id}</p><h2 id="edit-ticket-title" className="mt-1 text-lg font-extrabold text-[#173f38]">تعديل بيانات التذكرة</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose} aria-label="إغلاق"><X size={19} /></button></div><div className="grid gap-4 p-6 md:grid-cols-3"><FormInput label="اسم العميل" value={form.passengerName} onChange={value => update("passengerName", value)} /><FormInput label="الجنسية" value={form.nationality} onChange={value => update("nationality", value)} /><FormInput label="رقم الهاتف" value={form.phone} onChange={value => update("phone", value)} direction="ltr" /><FormInput label="رقم الجواز" value={form.passportNumber} onChange={value => update("passportNumber", value)} /><FormInput label="عدد الشنط" value={form.luggageCount} onChange={value => update("luggageCount", value)} type="number" /><FormInput label="تاريخ الميلاد" value={form.birthDate} onChange={value => update("birthDate", value)} type="date" /><FormSelect label="النوع" value={form.passengerType} onChange={value => update("passengerType", value)} options={["بالغ", "طفل"]} /><FormSelect label="نوع الدفع" value={form.paymentMethod} onChange={value => update("paymentMethod", value)} options={["نقدي", "شبكة"]} /><FormInput label="رقم المقعد" value={form.seatNumber} onChange={value => update("seatNumber", value)} type="number" /><FormInput label="إجمالي سعر التذكرة" value={form.ticketPrice} onChange={value => update("ticketPrice", value)} type="number" /><FormInput label="عمولة السائق (اختيارية)" value={form.driverCommission} onChange={value => update("driverCommission", value)} type="number" placeholder="تُحتسب صفراً عند تركها فارغة" /><label className="block text-[10px] font-bold text-[#4e6860]">صافي إيراد المكتب<input className="input-control mt-2 border-[#9ac8b0] bg-[#f2faf4] font-extrabold text-[#287a5d]" value={hasTicketPrice && financials.valid ? `${currency(financials.officeRevenue)} ر.س` : ""} readOnly /></label></div><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" disabled={saveReservation.isPending || !hasTicketPrice || !financials.valid || !form.passengerName.trim() || !form.phone.trim() || !form.nationality.trim() || !form.passportNumber.trim()} onClick={save}><Save size={15} /> حفظ تعديل التذكرة</button></div></div></div>;
}

function FormInput({ label, value, onChange, placeholder, type = "text", readOnly, direction }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; readOnly?: boolean; direction?: "ltr" | "rtl" }) { return <label className="block text-[10px] font-bold text-[#4e6860]">{label}<input className="input-control mt-2" value={value} onChange={event => onChange(event.target.value)} placeholder={placeholder} type={type} readOnly={readOnly} dir={direction} /></label>; }
function FormSelect({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) { return <label className="block text-[10px] font-bold text-[#4e6860]">{label}<select className="input-control mt-2" value={value} onChange={event => onChange(event.target.value)}>{options.map(item => <option key={item}>{item}</option>)}</select></label>; }

function TripEditModal({ trip, onClose }: { trip: TripItem; onClose: () => void }) { const updateTrip = useBookingStore(state => state.updateTrip); const { isAuthenticated } = useAuth(); const utils = trpc.useUtils(); const updateMongoTrip = trpc.mongoBooking.trips.update.useMutation({ onSuccess: () => utils.mongoBooking.trips.list.invalidate() }); const [form, setForm] = useState({ route: trip.route, bus: trip.bus, driver: trip.driver, secondDriver: trip.secondDriver, date: trip.date, time: trip.time, capacity: String(trip.capacity), status: trip.status }); const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value })); const save = () => { const capacity = Number(form.capacity); if (!Number.isInteger(capacity) || capacity < trip.bookedSeats.length || capacity > 80) return; if (!isAuthenticated) { toast.info("سجّل الدخول أولاً لحفظ تعديل الرحلة بشكل دائم."); startLogin(); return; } const updates = { route: form.route, bus: form.bus, driver: form.driver, secondDriver: form.secondDriver, date: form.date, time: form.time, capacity, status: form.status as TripItem["status"] }; updateMongoTrip.mutate({ code: trip.code, routeName: updates.route, busNumber: updates.bus, primaryDriverName: updates.driver, secondDriverName: updates.secondDriver, departureDate: updates.date, departureTime: updates.time, capacity: updates.capacity, status: updates.status }, { onSuccess: () => { updateTrip(trip.code, updates); toast.success("تم حفظ تعديل الرحلة."); onClose(); }, onError: () => toast.error("تعذر حفظ تعديل الرحلة في MongoDB.") }); }; return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="edit-trip-title"><div className="modal-card"><div className="flex items-center justify-between border-b border-[#edf0ed] px-6 py-5"><div><p className="page-kicker">{trip.code}</p><h2 id="edit-trip-title" className="mt-1 text-lg font-extrabold text-[#173f38]">تعديل بيانات الرحلة</h2></div><button className="grid h-8 w-8 place-items-center rounded-lg text-[#789087] hover:bg-[#f3f6f3]" onClick={onClose} aria-label="إغلاق"><X size={19} /></button></div><div className="grid gap-4 p-6 sm:grid-cols-2"><FormInput label="المسار" value={form.route} onChange={value => update("route", value)} /><FormInput label="رقم الحافلة" value={form.bus} onChange={value => update("bus", value)} /><FormInput label="السائق الأول" value={form.driver} onChange={value => update("driver", value)} /><FormInput label="السائق الثاني" value={form.secondDriver} onChange={value => update("secondDriver", value)} /><FormInput label="التاريخ" value={form.date} onChange={value => update("date", value)} type="date" /><FormInput label="وقت المغادرة" value={form.time} onChange={value => update("time", value)} type="time" /><FormInput label={`عدد المقاعد (لا يقل عن ${trip.bookedSeats.length})`} value={form.capacity} onChange={value => update("capacity", value)} type="number" /><FormSelect label="حالة الرحلة" value={form.status} onChange={value => update("status", value)} options={["open", "boarding", "departed", "closed"]} /></div><div className="flex justify-end gap-2 border-t border-[#edf0ed] px-6 py-4"><button className="action-secondary" onClick={onClose}>إلغاء</button><button className="action-primary" onClick={save}><Save size={15} /> حفظ التعديل</button></div></div></div>; }
